    score_model = apps.get_model("core", "IdeaIndicatorScore")
    indicators = {}
    for position, (key, name, question, weight) in enumerate(DEFAULT_INDICATORS, start=1):
        indicator, _ = indicator_model.objects.get_or_create(
            key=key,
            defaults={"name": name, "question": question, "weight": weight, "position": position},
        )
        indicators[name] = indicator
    for idea in idea_model.objects.iterator():
        details = idea.innovation_details or {}
        rationales = idea.innovation_rationales or {}
        score_model.objects.bulk_create(
            [
                score_model(
                    idea_id=idea.pk,
                    indicator_id=indicator.pk,
                    score=details.get(name),
                    rationale=rationales.get(name, ""),
                )
                for name, indicator in indicators.items()
                if name in details or name in rationales
            ],
            ignore_conflicts=True,
        )


